<?php
/**
 * ChatHelp — apply-appicon (CH_APPICON) — App/PWA launcher ikonu senkron.
 *  SORUN: manifest.json hala ANTRASIT (§) icon-192/512.png'ye isaret ediyordu;
 *  app'e yuklenince antrasit ikon geliyordu. Play Store'daki NAVY "CH" bubble
 *  ikonuyla ayni olacak sekilde duzeltir.
 *   [1] Navy 512 PNG (base64 gomulu, mobile/assets/icon-512.png ile ayni) diske
 *       yazilir: icon-512-v2.png + (GD ile 192'ye kucultulup) icon-192-v2.png.
 *       GD yoksa 512 kopyalanir (tarayici olceklendirir).
 *   [2] ESKI icon-192.png / icon-512.png de navy ile UZERINE yazilir (antrasit
 *       tamamen kalkar; TWA/eski referanslar da navy gorur).
 *   [3] manifest.json icindeki icon-192.png->icon-192-v2.png, icon-512.png->
 *       icon-512-v2.png (cache-bust: yuklu app manifest yenileyince yeni ikon).
 *  Lint/dogrulama + opcache reset.
 * KULLANIM: pull2.php?key=...&files=apply-appicon.php
 */
header('Content-Type: text/plain; charset=UTF-8');
error_reporting(E_ERROR | E_PARSE);
echo "apply-appicon BASLADI OK (PHP ".PHP_VERSION.")\n\n";

$D = __DIR__;
$b64 = '';
$png = base64_decode($b64);
if ($png===false || strlen($png) < 5000) exit("HATA: gomulu PNG cozulENEDI (".strlen((string)$png)." B)\n");
echo "  navy 512 PNG cozuldu: ".strlen($png)." B\n";

/* ── [1] navy 512 -> icon-512-v2.png ── */
$w = @file_put_contents("$D/icon-512-v2.png", $png);
echo ($w!==false && $w>5000) ? "  ✓ icon-512-v2.png yazildi ($w B)\n" : "  ✗ icon-512-v2.png YAZILAMADI\n";

/* ── 192'ye kucult (GD varsa), yoksa 512 kopyala ── */
$made192 = false;
if (function_exists('imagecreatefromstring') && function_exists('imagescale')) {
  $im = @imagecreatefromstring($png);
  if ($im) {
    $sm = @imagescale($im, 192, 192);
    if ($sm) {
      @imagesavealpha($sm, true);
      if (@imagepng($sm, "$D/icon-192-v2.png")) { $made192 = true; echo "  ✓ icon-192-v2.png (GD 192x192)\n"; }
      @imagedestroy($sm);
    }
    @imagedestroy($im);
  }
}
if (!$made192) { @file_put_contents("$D/icon-192-v2.png", $png); echo "  ✓ icon-192-v2.png (GD yok -> 512 kopyalandi)\n"; }

/* ── [2] ESKI dosyalari da navy yap (antrasit tamamen kalksin) ── */
@copy("$D/icon-512-v2.png", "$D/icon-512.png");
@copy("$D/icon-192-v2.png", "$D/icon-192.png");
echo "  ✓ eski icon-192.png / icon-512.png navy ile guncellendi\n";

/* ── [3] manifest.json'u yeni yollara isaret ettir ── */
$mf = "$D/manifest.json";
$m = @file_get_contents($mf);
if ($m===false) { echo "  ! manifest.json okunamadi (atlandi)\n"; }
else {
  $before = $m;
  $m = str_replace('icon-512.png', 'icon-512-v2.png', $m);
  $m = str_replace('icon-192.png', 'icon-192-v2.png', $m);
  /* zaten -v2 varsa cift olmasin */
  $m = str_replace('icon-512-v2-v2.png', 'icon-512-v2.png', $m);
  $m = str_replace('icon-192-v2-v2.png', 'icon-192-v2.png', $m);
  if ($m !== $before) {
    if (json_decode($m)===null && json_last_error()!==JSON_ERROR_NONE) {
      echo "  ✗ manifest JSON bozulacakti — DEGISTIRILMEDI\n";
    } else {
      @copy($mf, $mf.'.bak-'.date('Ymd-His'));
      @file_put_contents($mf, $m);
      echo "  ✓ manifest.json guncellendi (ikon yollari -> -v2)\n";
    }
  } else {
    echo "  = manifest.json zaten -v2 (degisiklik yok)\n";
  }
}

if (function_exists('opcache_reset')) @opcache_reset();
echo "\n✓ TAMAM. App'i tamamen kapat + yeniden ac (SW cache reset zaten var).\n";
echo "  Yeni yuklemelerde/manifest yenilenince NAVY CH ikonu gelir.\n";
echo "  NOT: Play Store TWA ise launcher ikonu APK'ya gomulu — yeni build gerekir;\n";
echo "  tarayicidan 'Ana ekrana ekle' PWA'da bu duzeltme aninda gecerli.\n";
